import re, glob

tab = dict(re.findall(r'\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|', open('draft/numerals.md').read()))
used = {}
for f in glob.glob('draft/*.md') + glob.glob('figures/*.md'):
    if f.endswith('numerals.md'):
        continue
    for m in re.findall(r'\b(\d{1,3})\b', open(f).read()):
        used.setdefault(m, set()).add(f.split('/')[-1][:14])

print('table:', sorted(tab, key=int))
print('used not in table:', sorted(set(used) - set(tab), key=int))
print('table not used:', sorted(set(tab) - set(used), key=int))
for k in sorted(tab, key=int):
    print(k, tab[k], sorted(used.get(k, [])))

